<?php
                $list = rows($pdo, 'SELECT r.*, t.full_name, rm.room_number, b.name AS building_name FROM rentals r JOIN tenants t ON t.id=r.tenant_id JOIN rooms rm ON rm.id=r.room_id JOIN kos_buildings b ON b.id=rm.building_id ORDER BY r.created_at DESC');
            ?>
                <div class="page-actions"><p>Pantau pelanggan, kamar, dan periode masa sewa.</p><a class="button primary" href="index.php?page=rental_form">＋ Sewa baru</a></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>Pelanggan</th><th>Gedung / kamar</th><th>Periode</th><th>Tarif bulanan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
                    <?php foreach ($list as $row): ?><tr><td><strong><?= e($row['full_name']) ?></strong></td><td><?= e($row['building_name']) ?><small class="subline">Kamar <?= e($row['room_number']) ?></small></td><td><?= e(date_id($row['start_date'])) ?> – <?= e(date_id($row['end_date'])) ?></td><td><?= e(money($row['monthly_rate'])) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e(status_label($row['status'])) ?></span></td><td><?php if (in_array($row['status'], ['active', 'upcoming'], true)): ?><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="rental_status"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><select name="status" aria-label="Status sewa"><option value="ended">Akhiri</option><option value="cancelled">Batalkan</option></select><button class="text-button" type="submit">Simpan</button></form><?php endif; ?></td></tr><?php endforeach; ?>
                    <?php if (!$list): ?><tr><td colspan="6" class="no-data">Belum ada masa sewa.</td></tr><?php endif; ?></tbody></table></div></div>
            